// --- Configuration ---
const PARTICLE_COUNT = 20000;
const SWARM_FORCE = 0.5; // Much stronger attraction for "fast actions"
const SHAPE_FORCE = 0.2; // Snap to shape faster
const DAMPING = 0.96; // Less drag = faster movement (0.96 is very slippery)
const PINCH_THRESHOLD = 0.08;
const DUEL_STRENGTH = 3000;
const SOFTENING = 50;
const MAX_FORCE = 5.0;
const MAX_VEL = 30;
const FILAMENT_RADIUS = 80;
const FILAMENT_FORCE = 0.8;
const FLOW_SPEED = 1.5;
const SUPERNOVA_TRIGGER_DIST = 150;
const SUPERNOVA_DETONATE_DIST = 40;
const EXPLOSION_FORCE = 80;
const COOLDOWN_DURATION = 1.5;
const PINCH_BOOST_MULTIPLIER = 3.0;
const COLOR_POS = { r: 0.3, g: 0.7, b: 1.0 };
const COLOR_NEG = { r: 1.0, g: 0.3, b: 0.5 };
const COLOR_FLASH = { r: 1.0, g: 1.0, b: 1.0 };
const RENDER_PIXEL_RATIO = Math.min(window.devicePixelRatio || 1, 1.35);

// --- State ---
let currentShape = 'swarm'; // swarm, heart, saturn, flower, fireworks, duel
let targetPositions = null; // Float32Array of target x,y,z for shape mode
let width = window.innerWidth;
let height = window.innerHeight;

// Gesture State
let isSwarmMode = true;
let isPinching = false;
let pinchDistance = 0;
let handCenter = new THREE.Vector3();
let indexFingerTip = new THREE.Vector3();
let lastHandTime = 0; // Track when hand was last seen
const hands = {
    left: { active: false, pos: new THREE.Vector3(), pinch: false, charge: 1, lastSeen: 0 },
    right: { active: false, pos: new THREE.Vector3(), pinch: false, charge: -1, lastSeen: 0 }
};
const detectedIndexPoints = [
    { pos: new THREE.Vector3(), pinch: false, pinchDistance: 1, lastSeen: 0 },
    { pos: new THREE.Vector3(), pinch: false, pinchDistance: 1, lastSeen: 0 }
];
const supernova = {
    state: 'IDLE',
    charge: 0,
    explosionTime: 0,
    epicenter: new THREE.Vector3()
};

// Autonomous duel attractors (used when no hands detected)
const autoDuel = {
    angle: 0,
    radius: 280,
    leftPos: new THREE.Vector3(),
    rightPos: new THREE.Vector3(),
    pulsePhase: 0
};

// --- Three.js Setup ---
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x000000, 0.0006);

const camera = new THREE.PerspectiveCamera(75, width / height, 1, 4000);
camera.position.z = 800;

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(width, height);
renderer.setPixelRatio(RENDER_PIXEL_RATIO);
// Enable auto clear false for potential trail effects if desired, but sticking to standard for clarity
document.body.appendChild(renderer.domElement);

// --- Particle System ---
const geometry = new THREE.BufferGeometry();
const pPos = new Float32Array(PARTICLE_COUNT * 3);
const pVel = new Float32Array(PARTICLE_COUNT * 3);
const pCol = new Float32Array(PARTICLE_COUNT * 3);
const originalColors = new Float32Array(PARTICLE_COUNT * 3); // Store for reverting
const shapeTargets = new Float32Array(PARTICLE_COUNT * 3);

// Initial State
for (let i = 0; i < PARTICLE_COUNT; i++) {
    const r = 1000 * Math.random();
    pPos[i * 3] = (Math.random() - 0.5) * r;
    pPos[i * 3 + 1] = (Math.random() - 0.5) * r;
    pPos[i * 3 + 2] = (Math.random() - 0.5) * r;

    // Cosmic Colors Palette: Electric Blue, Deep Purple, Star Gold, Nebula Cyan
    const choice = Math.random();
    let rC, gC, bC;
    if (choice < 0.3) { // Electric Blue
        rC = 0.1; gC = 0.5; bC = 1.0;
    } else if (choice < 0.5) { // Deep Purple
        rC = 0.6; gC = 0.0; bC = 1.0;
    } else if (choice < 0.7) { // Star Gold
        rC = 1.0; gC = 0.8; bC = 0.2;
    } else { // Nebula Cyan
        rC = 0.0; gC = 1.0; bC = 0.9;
    }

    pCol[i * 3] = rC;
    pCol[i * 3 + 1] = gC;
    pCol[i * 3 + 2] = bC;

    // Save original for smooth transition back
    originalColors[i * 3] = rC;
    originalColors[i * 3 + 1] = gC;
    originalColors[i * 3 + 2] = bC;
}

geometry.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
geometry.setAttribute('color', new THREE.BufferAttribute(pCol, 3));

const material = new THREE.PointsMaterial({
    size: 2.0,
    vertexColors: true,
    blending: THREE.AdditiveBlending,
    depthTest: false,
    transparent: true,
    opacity: 0.8
});

const particles = new THREE.Points(geometry, material);
scene.add(particles);

// --- 3D Reality Starfield (Background) ---
const starGeo = new THREE.BufferGeometry();
const STAR_COUNT = 9000; // Static backdrop, kept light so tracking stays smooth
const sPos = new Float32Array(STAR_COUNT * 3);
const sCol = new Float32Array(STAR_COUNT * 3);

for (let i = 0; i < STAR_COUNT; i++) {
    // Spread stars very wide for parallax
    const r = 2000 + Math.random() * 3000; // Far background
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);

    sPos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
    sPos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
    sPos[i * 3 + 2] = r * Math.cos(phi);

    // Star Colors: mostly white/blue-white, some red dwarfs
    const type = Math.random();
    let c = new THREE.Color();
    if (type > 0.9) c.setHex(0xffaaaa); // Reddish
    else if (type > 0.7) c.setHex(0xaaccff); // Blueish
    else c.setHex(0xffffff); // White

    // Random brightness variation
    const brightness = 0.5 + Math.random() * 0.5;
    sCol[i * 3] = c.r * brightness;
    sCol[i * 3 + 1] = c.g * brightness;
    sCol[i * 3 + 2] = c.b * brightness;
}

starGeo.setAttribute('position', new THREE.BufferAttribute(sPos, 3));
starGeo.setAttribute('color', new THREE.BufferAttribute(sCol, 3));

const starMat = new THREE.PointsMaterial({
    size: 1.5,
    vertexColors: true,
    fog: false, // Stars pierce the fog
    transparent: true,
    opacity: 0.8
});

const starField = new THREE.Points(starGeo, starMat);
// IMPORTANT: Frustum culling off ensures they don't flicker if they are "too far" or big bounds
starField.frustumCulled = false;
scene.add(starField);

// --- Shared Helpers ---
const origin = new THREE.Vector3(0, 0, 0);
const singleForceOut = { vx: 0, vy: 0, vz: 0 };

function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
}

function lerpValue(a, b, t) {
    return a + (b - a) * t;
}

function resetSupernova() {
    supernova.state = 'IDLE';
    supernova.charge = 0;
    supernova.explosionTime = 0;
    supernova.epicenter.set(0, 0, 0);
}

function worldPosFromLandmark(indexTip, target) {
    const vFOV = camera.fov * Math.PI / 180;
    const visibleHeight = 2 * Math.tan(vFOV / 2) * camera.position.z;
    const visibleWidth = visibleHeight * camera.aspect;

    const x = (1 - indexTip.x - 0.5) * visibleWidth;
    const y = -(indexTip.y - 0.5) * visibleHeight;
    target.set(x, y, 0);
}

function updatePrimaryHandState() {
    const primary = hands.left.active ? hands.left : (hands.right.active ? hands.right : null);

    if (primary) {
        indexFingerTip.copy(primary.pos);
        isPinching = primary.pinch;
        lastHandTime = primary.lastSeen;
        handCenter.copy(indexFingerTip);
    } else {
        isPinching = false;
    }
}

function getActiveHands() {
    const active = [];
    if (hands.left.active) active.push(hands.left);
    if (hands.right.active) active.push(hands.right);
    return active;
}

function assignIndexPointToHand(hand, detected, now) {
    const lerpFactor = now - hand.lastSeen > 250 ? 0.3 : 0.82;
    if (hand.lastSeen === 0) {
        hand.pos.copy(detected.pos);
    } else {
        hand.pos.lerp(detected.pos, lerpFactor);
    }

    hand.active = true;
    hand.pinch = detected.pinch;
    hand.lastSeen = now;
}

function applySingleHandForces(px, py, pz, vx, vy, vz, target) {
    const dx = target.x - px;
    const dy = target.y - py;
    const dz = target.z - pz;

    const distSq = dx * dx + dy * dy + dz * dz + 100;
    const pull = 2000 / distSq;

    vx += dx * pull * SWARM_FORCE;
    vy += dy * pull * SWARM_FORCE;
    vz += dz * pull * SWARM_FORCE;

    const distToFinger = Math.sqrt(dx * dx + dy * dy + dz * dz) + 1;
    if (distToFinger < 150) {
        const push = (150 - distToFinger) * 0.05;
        vx -= (dx / distToFinger) * push;
        vy -= (dy / distToFinger) * push;
        vz -= (dz / distToFinger) * push;
    }

    vx += dx * 0.0002;
    vy += dy * 0.0002;
    vz += dz * 0.0002;

    const dist = Math.sqrt(dx * dx + dy * dy + 100);
    vx += (dy / dist) * 0.5;
    vy -= (dx / dist) * 0.5;

    const distFromCenterSq = px * px + py * py + pz * pz;
    if (distFromCenterSq > 500000) {
        vx -= px * 0.0001;
        vy -= py * 0.0001;
        vz -= pz * 0.0001;
    }

    singleForceOut.vx = vx;
    singleForceOut.vy = vy;
    singleForceOut.vz = vz;
    return singleForceOut;
}

function triggerSupernova(positions, colors, midpoint) {
    supernova.state = 'EXPLODING';
    supernova.charge = 1;
    supernova.explosionTime = 0;
    supernova.epicenter.copy(midpoint);

    for (let i = 0; i < PARTICLE_COUNT; i++) {
        const ix = i * 3;
        const iy = ix + 1;
        const iz = ix + 2;

        const rx = positions[ix] - supernova.epicenter.x + (Math.random() - 0.5) * 8;
        const ry = positions[iy] - supernova.epicenter.y + (Math.random() - 0.5) * 8;
        const rz = positions[iz] - supernova.epicenter.z + (Math.random() - 0.5) * 8;
        const dist = Math.sqrt(rx * rx + ry * ry + rz * rz) || 1;

        pVel[ix] += (rx / dist) * EXPLOSION_FORCE;
        pVel[iy] += (ry / dist) * EXPLOSION_FORCE;
        pVel[iz] += (rz / dist) * EXPLOSION_FORCE;

        colors[ix] = COLOR_FLASH.r;
        colors[iy] = COLOR_FLASH.g;
        colors[iz] = COLOR_FLASH.b;
    }
}

// --- Shape Generators ---
function generateShape(type) {
    const arr = new Float32Array(PARTICLE_COUNT * 3);

    for (let i = 0; i < PARTICLE_COUNT; i++) {
        let x = 0, y = 0, z = 0;

        if (type === 'heart') {
            const phi = Math.random() * Math.PI * 2;
            const theta = Math.random() * Math.PI; // For Z volume
            const t = phi;
            let hx = 16 * Math.pow(Math.sin(t), 3);
            let hy = 13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t);
            let scale = 15;
            x = hx * scale;
            y = hy * scale;
            z = (Math.random() - 0.5) * 100;
        }
        else if (type === 'saturn') {
            const isRing = Math.random() > 0.4;
            if (isRing) {
                const angle = Math.random() * Math.PI * 2;
                const r = 250 + Math.random() * 150;
                x = Math.cos(angle) * r;
                z = Math.sin(angle) * r;
                y = (Math.random() - 0.5) * 10;
            } else {
                const r = 180;
                const theta = Math.random() * Math.PI * 2;
                const phi = Math.acos(2 * Math.random() - 1);
                x = r * Math.sin(phi) * Math.cos(theta);
                y = r * Math.sin(phi) * Math.sin(theta);
                z = r * Math.cos(phi);
            }
            const tilt = 0.4;
            const tx = x;
            x = tx * Math.cos(tilt) - y * Math.sin(tilt);
            y = tx * Math.sin(tilt) + y * Math.cos(tilt);
        }
        else if (type === 'flower') {
            const k = 4;
            const theta = Math.random() * Math.PI * 2;
            const r_curve = Math.cos(k * theta);
            const r = 300 * Math.abs(r_curve) + 50;
            x = r * Math.cos(theta);
            y = r * Math.sin(theta);
            z = -r_curve * 100 + (Math.random() - 0.5) * 50;
        }
        else if (type === 'fireworks') {
            const r = 300 + Math.random() * 300;
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.acos(2 * Math.random() - 1);
            x = r * Math.sin(phi) * Math.cos(theta);
            y = r * Math.sin(phi) * Math.sin(theta);
            z = r * Math.cos(phi);
        }

        arr[i * 3] = x;
        arr[i * 3 + 1] = y;
        arr[i * 3 + 2] = z;
    }
    return arr;
}

// Global UI function
window.setShape = (shape) => {
    currentShape = shape;
    isSwarmMode = (shape === 'swarm');
    const isDuelMode = (shape === 'duel');
    if (!isDuelMode) resetSupernova();

    // Close manual when switching modes
    const manualPanel = document.getElementById('manual');
    if (manualPanel) manualPanel.classList.remove('open');

    if (!isSwarmMode && !isDuelMode) {
        const targets = generateShape(shape);
        for (let i = 0; i < targets.length; i++) {
            shapeTargets[i] = targets[i];
        }
    }

    // Reset auto duel angle for fresh start
    if (isDuelMode) {
        autoDuel.angle = 0;
        autoDuel.pulsePhase = 0;
    }

    document.querySelectorAll('#ui button').forEach(b => b.classList.remove('active'));
    const btn = Array.from(document.querySelectorAll('#ui button')).find(b => b.innerText.toLowerCase().includes(shape));
    if (btn) btn.classList.add('active');

    for (let i = 0; i < PARTICLE_COUNT * 3; i++) {
        pVel[i] *= 0.1;
    }
}

window.toggleFullscreen = () => {
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen();
    } else {
        if (document.exitFullscreen) {
            document.exitFullscreen();
        }
    }
}

window.toggleManual = (evt) => {
    if (evt) evt.stopPropagation();
    const panel = document.getElementById('manual');
    if (panel) {
        panel.classList.toggle('open');
    }
}

// Close manual when clicking outside
document.addEventListener('click', (e) => {
    const panel = document.getElementById('manual');
    const manualBtn = Array.from(document.querySelectorAll('#ui button')).find(b => b.innerText.toLowerCase().includes('manual'));
    if (panel && panel.classList.contains('open') && !panel.contains(e.target) && e.target !== manualBtn) {
        panel.classList.remove('open');
    }
});


// --- MediaPipe Hands Logic ---
const videoElement = document.getElementsByClassName('input_video')[0];

function onResults(results) {
    document.getElementById('loading').style.display = 'none';

    hands.left.active = false;
    hands.right.active = false;
    hands.left.pinch = false;
    hands.right.pinch = false;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
        const now = Date.now();
        let detectedCount = 0;

        for (let i = 0; i < results.multiHandLandmarks.length && detectedCount < 2; i++) {
            const landmarks = results.multiHandLandmarks[i];
            const indexTip = landmarks[8];
            const thumbTip = landmarks[4];
            const wrist = landmarks[0];

            const handSize = Math.sqrt(
                Math.pow(indexTip.x - wrist.x, 2) +
                Math.pow(indexTip.y - wrist.y, 2)
            );

            if (handSize < 0.05 || handSize > 0.8) {
                continue;
            }

            const dx = indexTip.x - thumbTip.x;
            const dy = indexTip.y - thumbTip.y;
            const dist = Math.sqrt(dx * dx + dy * dy);
            const detected = detectedIndexPoints[detectedCount];

            worldPosFromLandmark(indexTip, detected.pos);
            detected.pinch = dist < PINCH_THRESHOLD;
            detected.pinchDistance = dist;
            detected.lastSeen = now;
            pinchDistance = dist;
            lastHandTime = now;
            detectedCount++;
        }

        if (detectedCount === 2 && detectedIndexPoints[0].pos.x > detectedIndexPoints[1].pos.x) {
            const tmpX = detectedIndexPoints[0].pos.x;
            const tmpY = detectedIndexPoints[0].pos.y;
            const tmpZ = detectedIndexPoints[0].pos.z;
            const tmpPinch = detectedIndexPoints[0].pinch;
            const tmpDist = detectedIndexPoints[0].pinchDistance;

            detectedIndexPoints[0].pos.copy(detectedIndexPoints[1].pos);
            detectedIndexPoints[0].pinch = detectedIndexPoints[1].pinch;
            detectedIndexPoints[0].pinchDistance = detectedIndexPoints[1].pinchDistance;

            detectedIndexPoints[1].pos.set(tmpX, tmpY, tmpZ);
            detectedIndexPoints[1].pinch = tmpPinch;
            detectedIndexPoints[1].pinchDistance = tmpDist;
        }

        if (detectedCount > 0) assignIndexPointToHand(hands.left, detectedIndexPoints[0], now);
        if (detectedCount > 1) assignIndexPointToHand(hands.right, detectedIndexPoints[1], now);

        updatePrimaryHandState();
    } else {
        updatePrimaryHandState();
    }
}

const handTracker = new Hands({ locateFile: (file) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}` });
handTracker.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.4, minTrackingConfidence: 0.4 });
handTracker.onResults(onResults);

const cameraUtils = new Camera(videoElement, {
    onFrame: async () => await handTracker.send({ image: videoElement }),
    width: 480, height: 360
});
cameraUtils.start();


// --- Animation Loop ---
let time = 0;

function animate() {
    requestAnimationFrame(animate);
    time += 0.01;

    material.color.setHex(0xffffff);

    const positions = particles.geometry.attributes.position.array;
    const colors = particles.geometry.attributes.color.array;
    const isDuelMode = currentShape === 'duel';
    const activeHandCount = (hands.left.active ? 1 : 0) + (hands.right.active ? 1 : 0);
    const singleActiveHand = hands.left.active ? hands.left : (hands.right.active ? hands.right : null);
    let hasTwoHands = isDuelMode && hands.left.active && hands.right.active;

    let midpointX = 0, midpointY = 0, midpointZ = 0;
    let axisX = 1, axisY = 0, axisZ = 0;
    let handDistance = 1;

    // Auto-center if hand is lost
    if ((isSwarmMode || isDuelMode) && Date.now() - lastHandTime > 1000) {
        indexFingerTip.lerp(origin, 0.05);
        isPinching = false;
    }

    // Autonomous duel attractors - orbiting gravity wells when no hands
    const useAutoDuel = isDuelMode && activeHandCount === 0;
    if (useAutoDuel) {
        autoDuel.angle += 0.008;
        autoDuel.pulsePhase += 0.02;
        const pulse = 1.0 + 0.3 * Math.sin(autoDuel.pulsePhase);
        const r = autoDuel.radius * pulse;
        autoDuel.leftPos.set(
            Math.cos(autoDuel.angle) * r,
            Math.sin(autoDuel.angle * 0.7) * r * 0.6,
            Math.sin(autoDuel.angle * 0.3) * 80
        );
        autoDuel.rightPos.set(
            -Math.cos(autoDuel.angle) * r,
            -Math.sin(autoDuel.angle * 0.7) * r * 0.6,
            -Math.sin(autoDuel.angle * 0.3) * 80
        );
        midpointX = 0;
        midpointY = 0;
        midpointZ = 0;
        const rawAxisX = autoDuel.rightPos.x - autoDuel.leftPos.x;
        const rawAxisY = autoDuel.rightPos.y - autoDuel.leftPos.y;
        const rawAxisZ = autoDuel.rightPos.z - autoDuel.leftPos.z;
        handDistance = Math.sqrt(rawAxisX * rawAxisX + rawAxisY * rawAxisY + rawAxisZ * rawAxisZ);
        handDistance = Math.max(handDistance, 1.0);
        axisX = rawAxisX / handDistance;
        axisY = rawAxisY / handDistance;
        axisZ = rawAxisZ / handDistance;
    }

    if (hasTwoHands) {
        midpointX = (hands.left.pos.x + hands.right.pos.x) * 0.5;
        midpointY = (hands.left.pos.y + hands.right.pos.y) * 0.5;
        midpointZ = (hands.left.pos.z + hands.right.pos.z) * 0.5;

        const rawAxisX = hands.right.pos.x - hands.left.pos.x;
        const rawAxisY = hands.right.pos.y - hands.left.pos.y;
        const rawAxisZ = hands.right.pos.z - hands.left.pos.z;
        const rawHandDistance = Math.sqrt(rawAxisX * rawAxisX + rawAxisY * rawAxisY + rawAxisZ * rawAxisZ);
        handDistance = Math.max(rawHandDistance, 1.0);
        axisX = rawAxisX / handDistance;
        axisY = rawAxisY / handDistance;
        axisZ = rawAxisZ / handDistance;

        if (supernova.state !== 'EXPLODING' && supernova.state !== 'COOLDOWN') {
            if (rawHandDistance < SUPERNOVA_DETONATE_DIST) {
                triggerSupernova(positions, colors, new THREE.Vector3(midpointX, midpointY, midpointZ));
            } else if (rawHandDistance < SUPERNOVA_TRIGGER_DIST) {
                supernova.state = 'CHARGING';
                supernova.charge = 1 - (rawHandDistance / SUPERNOVA_TRIGGER_DIST);
                supernova.epicenter.set(midpointX, midpointY, midpointZ);
            } else if (supernova.state === 'CHARGING') {
                resetSupernova();
            }
        }
    } else if (isDuelMode && supernova.state === 'CHARGING') {
        resetSupernova();
    }

    if (supernova.state === 'EXPLODING') {
        supernova.explosionTime += 0.016;
        if (supernova.explosionTime > 0.25) {
            supernova.state = 'COOLDOWN';
            supernova.explosionTime = 0;
        }
    } else if (supernova.state === 'COOLDOWN') {
        supernova.explosionTime += 0.016;
        if (supernova.explosionTime > COOLDOWN_DURATION) {
            resetSupernova();
        }
    }

    const timeScale = time * 3.0;

    // Physics Logic (Matches User Request: SWARM_FORCE 0.5, DAMPING 0.96)
    for (let i = 0; i < PARTICLE_COUNT; i++) {
        const ix = i * 3;
        const iy = i * 3 + 1;
        const iz = i * 3 + 2;

        let px = positions[ix];
        let py = positions[iy];
        let pz = positions[iz];

        let vx = pVel[ix];
        let vy = pVel[iy];
        let vz = pVel[iz];

        let tr, tg, tb;

        if (isDuelMode && (hasTwoHands || useAutoDuel)) {
            // Use actual hands or auto duel positions for coloring
            const lpX = hasTwoHands ? hands.left.pos.x : autoDuel.leftPos.x;
            const lpY = hasTwoHands ? hands.left.pos.y : autoDuel.leftPos.y;
            const lpZ = hasTwoHands ? hands.left.pos.z : autoDuel.leftPos.z;
            const rpX = hasTwoHands ? hands.right.pos.x : autoDuel.rightPos.x;
            const rpY = hasTwoHands ? hands.right.pos.y : autoDuel.rightPos.y;
            const rpZ = hasTwoHands ? hands.right.pos.z : autoDuel.rightPos.z;

            const dlx = lpX - px, dly = lpY - py, dlz = lpZ - pz;
            const drx = rpX - px, dry = rpY - py, drz = rpZ - pz;
            const infL = DUEL_STRENGTH / (dlx * dlx + dly * dly + dlz * dlz + SOFTENING * SOFTENING);
            const infR = DUEL_STRENGTH / (drx * drx + dry * dry + drz * drz + SOFTENING * SOFTENING);
            const leftRatio = infL / (infL + infR || 1);

            tr = lerpValue(COLOR_NEG.r, COLOR_POS.r, leftRatio);
            tg = lerpValue(COLOR_NEG.g, COLOR_POS.g, leftRatio);
            tb = lerpValue(COLOR_NEG.b, COLOR_POS.b, leftRatio);

            if (hasTwoHands) {
                if (hands.left.pinch) {
                    tr = lerpValue(tr, 1.0, leftRatio);
                    tg = lerpValue(tg, 0.8, leftRatio);
                    tb = lerpValue(tb, 0.0, leftRatio);
                }
                if (hands.right.pinch) {
                    tr = lerpValue(tr, 1.0, 1.0 - leftRatio);
                    tg = lerpValue(tg, 0.8, 1.0 - leftRatio);
                    tb = lerpValue(tb, 0.0, 1.0 - leftRatio);
                }
            }

            if (supernova.state === 'CHARGING') {
                const flash = supernova.charge * 0.7;
                tr = lerpValue(tr, COLOR_FLASH.r, flash);
                tg = lerpValue(tg, COLOR_FLASH.g, flash);
                tb = lerpValue(tb, COLOR_FLASH.b, flash);
            } else if (supernova.state === 'EXPLODING') {
                tr = COLOR_FLASH.r;
                tg = COLOR_FLASH.g;
                tb = COLOR_FLASH.b;
            } else if (supernova.state === 'COOLDOWN') {
                // Fade from white back to duel colors during cooldown
                const cooldownProgress = supernova.explosionTime / COOLDOWN_DURATION;
                tr = lerpValue(COLOR_FLASH.r, tr, cooldownProgress);
                tg = lerpValue(COLOR_FLASH.g, tg, cooldownProgress);
                tb = lerpValue(COLOR_FLASH.b, tb, cooldownProgress);
            }
        } else if (isPinching) {
            tr = 1.0;
            tg = 0.5 + 0.5 * Math.sin(timeScale + i * 0.005);
            tb = 0.0;
        } else {
            tr = originalColors[ix];
            tg = originalColors[iy];
            tb = originalColors[iz];
        }

        colors[ix] += (tr - colors[ix]) * 0.12;
        colors[iy] += (tg - colors[iy]) * 0.12;
        colors[iz] += (tb - colors[iz]) * 0.12;

        if (isDuelMode) {
            if (supernova.state === 'COOLDOWN') {
                // Let them float freely like a nebula, minimal gathering
                const gatherStrength = 0.001;
                vx -= px * gatherStrength;
                vy -= py * gatherStrength;
                vz -= pz * gatherStrength;
                
                // Add chaotic floating so they don't stick
                vx += (Math.random() - 0.5) * 1.5;
                vy += (Math.random() - 0.5) * 1.5;
                vz += (Math.random() - 0.5) * 1.5;
            } else if (supernova.state !== 'EXPLODING') {
                if (hasTwoHands) {
                    for (let h = 0; h < 2; h++) {
                        const hand = h === 0 ? hands.left : hands.right;
                        const rx = hand.pos.x - px;
                        const ry = hand.pos.y - py;
                        const rz = hand.pos.z - pz;
                        const distSq = rx * rx + ry * ry + rz * rz + SOFTENING * SOFTENING;
                        const dist = Math.sqrt(distSq);
                        const boost = hand.pinch ? PINCH_BOOST_MULTIPLIER : 1.0;
                        const forceMag = clamp((hand.charge * DUEL_STRENGTH * boost) / distSq, -MAX_FORCE, MAX_FORCE);

                        vx += (rx / dist) * forceMag;
                        vy += (ry / dist) * forceMag;
                        vz += (rz / dist) * forceMag;
                    }

                    const toPX = px - midpointX;
                    const toPY = py - midpointY;
                    const toPZ = pz - midpointZ;
                    const alongAxis = toPX * axisX + toPY * axisY + toPZ * axisZ;
                    const perpX = toPX - axisX * alongAxis;
                    const perpY = toPY - axisY * alongAxis;
                    const perpZ = toPZ - axisZ * alongAxis;
                    const perpDist = Math.sqrt(perpX * perpX + perpY * perpY + perpZ * perpZ);

                    if (perpDist < FILAMENT_RADIUS && Math.abs(alongAxis) < handDistance * 0.5) {
                        const pullStrength = (1 - perpDist / FILAMENT_RADIUS) * FILAMENT_FORCE;
                        const safePerpDist = Math.max(perpDist, 1.0);

                        vx -= (perpX / safePerpDist) * pullStrength;
                        vy -= (perpY / safePerpDist) * pullStrength;
                        vz -= (perpZ / safePerpDist) * pullStrength;

                        vx += axisX * FLOW_SPEED;
                        vy += axisY * FLOW_SPEED;
                        vz += axisZ * FLOW_SPEED;
                    }

                    if (supernova.state === 'CHARGING') {
                        const cx = midpointX - px;
                        const cy = midpointY - py;
                        const cz = midpointZ - pz;
                        const cdist = Math.sqrt(cx * cx + cy * cy + cz * cz) || 1;
                        const chargePull = supernova.charge * 5.0;
                        vx += (cx / cdist) * chargePull;
                        vy += (cy / cdist) * chargePull;
                        vz += (cz / cdist) * chargePull;
                    }
                } else if (activeHandCount === 1) {
                    const result = applySingleHandForces(px, py, pz, vx, vy, vz, singleActiveHand.pos);
                    vx = result.vx;
                    vy = result.vy;
                    vz = result.vz;
                } else {
                    // --- AUTONOMOUS DUEL MODE (no hands) ---
                    const lp = autoDuel.leftPos;
                    const rp = autoDuel.rightPos;

                    // Attract to left (positive charge)
                    const dlx = lp.x - px, dly = lp.y - py, dlz = lp.z - pz;
                    const dlSq = dlx * dlx + dly * dly + dlz * dlz + SOFTENING * SOFTENING;
                    const dlDist = Math.sqrt(dlSq);
                    const fL = clamp(DUEL_STRENGTH * 0.8 / dlSq, -MAX_FORCE, MAX_FORCE);
                    vx += (dlx / dlDist) * fL;
                    vy += (dly / dlDist) * fL;
                    vz += (dlz / dlDist) * fL;

                    // Repel from right (negative charge)
                    const drx = rp.x - px, dry = rp.y - py, drz = rp.z - pz;
                    const drSq = drx * drx + dry * dry + drz * drz + SOFTENING * SOFTENING;
                    const drDist = Math.sqrt(drSq);
                    const fR = clamp(-DUEL_STRENGTH * 0.8 / drSq, -MAX_FORCE, MAX_FORCE);
                    vx += (drx / drDist) * fR;
                    vy += (dry / drDist) * fR;
                    vz += (drz / drDist) * fR;

                    // Filament between auto attractors
                    const toPX = px - midpointX;
                    const toPY = py - midpointY;
                    const toPZ = pz - midpointZ;
                    const alongAxis = toPX * axisX + toPY * axisY + toPZ * axisZ;
                    const perpX = toPX - axisX * alongAxis;
                    const perpY = toPY - axisY * alongAxis;
                    const perpZ = toPZ - axisZ * alongAxis;
                    const perpDist = Math.sqrt(perpX * perpX + perpY * perpY + perpZ * perpZ);

                    if (perpDist < FILAMENT_RADIUS * 1.5 && Math.abs(alongAxis) < handDistance * 0.55) {
                        const pullStrength = (1 - perpDist / (FILAMENT_RADIUS * 1.5)) * FILAMENT_FORCE * 0.6;
                        const safePerpDist = Math.max(perpDist, 1.0);
                        vx -= (perpX / safePerpDist) * pullStrength;
                        vy -= (perpY / safePerpDist) * pullStrength;
                        vz -= (perpZ / safePerpDist) * pullStrength;
                        vx += axisX * FLOW_SPEED * 0.8;
                        vy += axisY * FLOW_SPEED * 0.8;
                        vz += axisZ * FLOW_SPEED * 0.8;
                    }

                    // Gentle boundary pull to keep particles visible
                    const distFromCenter = Math.sqrt(px * px + py * py + pz * pz);
                    if (distFromCenter > 600) {
                        const pullBack = (distFromCenter - 600) * 0.003;
                        vx -= (px / distFromCenter) * pullBack;
                        vy -= (py / distFromCenter) * pullBack;
                        vz -= (pz / distFromCenter) * pullBack;
                    }
                }
            }
        } else if (isSwarmMode) {
            // --- SWARM MODE ---
            if (Date.now() - lastHandTime > 1000) {
                // Majestic Flowing Wave Idle State (Polished)
                const distSq = px * px + py * py + pz * pz;
                const dist = Math.sqrt(distSq) || 1;
                
                // Spiral orbit but slower, more graceful
                const orbitSpeed = 8.0 / Math.pow(dist, 0.4); 
                vx -= (pz / dist) * orbitSpeed;
                vz += (px / dist) * orbitSpeed;
                
                // Flatten to a thick band, not a microscopic line
                if (Math.abs(py) > 50) {
                    vy -= py * 0.005;
                }
                
                // Add flowing wave motion so it looks alive and not static
                vy += Math.sin(px * 0.01 + timeScale) * 0.4;
                vy += Math.cos(pz * 0.01 + timeScale * 0.8) * 0.4;
                
                // Center gravity + dispersion (prevent gluing)
                if (dist > 900) {
                    vx -= (px / dist) * 0.2;
                    vy -= (py / dist) * 0.2;
                    vz -= (pz / dist) * 0.2;
                } else if (dist < 200) {
                    // Push out strongly from the center to avoid clumping
                    vx += (px / dist) * 0.8;
                    vz += (pz / dist) * 0.8;
                }
            } else {
                const result = applySingleHandForces(px, py, pz, vx, vy, vz, indexFingerTip);
                vx = result.vx;
                vy = result.vy;
                vz = result.vz;
            }
        } else {
            // --- SHAPE MODE ---
            const tx = shapeTargets[ix];
            const ty = shapeTargets[iy];
            const tz = shapeTargets[iz];

            let expansion = 1.0;

            const dx = (tx * expansion) - px;
            const dy = (ty * expansion) - py;
            const dz = (tz * expansion) - pz;

            vx += dx * SHAPE_FORCE;
            vy += dy * SHAPE_FORCE;
            vz += dz * SHAPE_FORCE;

            const fdx = indexFingerTip.x - px;
            const fdy = indexFingerTip.y - py;
            const fdist = Math.sqrt(fdx * fdx + fdy * fdy);
            if (fdist < 100) {
                vx -= fdx * 0.1;
                vy -= fdy * 0.1;
            }
        }

        vx += (Math.random() - 0.5) * 0.1;
        vy += (Math.random() - 0.5) * 0.1;
        vz += (Math.random() - 0.5) * 0.1;

        vx *= DAMPING;
        vy *= DAMPING;
        vz *= DAMPING;

        const speed = Math.sqrt(vx * vx + vy * vy + vz * vz);
        if (speed > MAX_VEL) {
            const scale = MAX_VEL / speed;
            vx *= scale;
            vy *= scale;
            vz *= scale;
        }

        positions[ix] += vx;
        positions[iy] += vy;
        positions[iz] += vz;

        pVel[ix] = vx;
        pVel[iy] = vy;
        pVel[iz] = vz;
    }

    particles.geometry.attributes.position.needsUpdate = true;
    particles.geometry.attributes.color.needsUpdate = true;

    scene.rotation.y = Math.sin(time * 0.1) * 0.1;

    renderer.render(scene, camera);
}

window.addEventListener('resize', () => {
    width = window.innerWidth;
    height = window.innerHeight;
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
    renderer.setSize(width, height);
});

animate();
